#include <algorithm>
using namespace std;

class Solution {
public:
    vector<int> countPairs(int n, vector<vector<int>>& edges, vector<int>& queries) {
        vector<int> deg(n + 1, 0);
        unordered_map<long long, int> shared;
        for (const auto& e : edges) {
            int u = e[0], v = e[1];
            deg[u]++;
            deg[v]++;
            if (u > v) swap(u, v);
            long long key = ((long long)u << 32) | v;
            shared[key]++;
        }

        vector<int> sorted_deg(deg.begin() + 1, deg.end());
        sort(sorted_deg.begin(), sorted_deg.end());

        vector<int> ans;
        ans.reserve(queries.size());

        for (int q : queries) {
            int count = 0;
            int l = 0, r = n - 1;
            while (l < r) {
                if (sorted_deg[l] + sorted_deg[r] > q) {
                    count += (r - l);
                    r--;
                } else {
                    l++;
                }
            }

            for (const auto& [key, edge_count] : shared) {
                int u = key >> 32;
                int v = key & 0xFFFFFFFFLL;
                if (deg[u] + deg[v] > q && deg[u] + deg[v] - edge_count <= q) {
                    count--;
                }
            }
            ans.push_back(count);
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int[] countPairs(int n, int[][] edges, int[] queries) {
        int[] deg = new int[n + 1];
        Map<Long, Integer> shared = new HashMap<>();
        for (int[] e : edges) {
            int u = e[0], v = e[1];
            deg[u]++;
            deg[v]++;
            if (u > v) { int t = u; u = v; v = t; }
            long key = (((long)u) << 32) | (v & 0xFFFFFFFFL);
            shared.put(key, shared.getOrDefault(key, 0) + 1);
        }

        int[] sortedDeg = new int[n];
        System.arraycopy(deg, 1, sortedDeg, 0, n);
        Arrays.sort(sortedDeg);

        int[] ans = new int[queries.length];
        for (int qi = 0; qi < queries.length; ++qi) {
            int q = queries[qi];
            int count = 0;
            int l = 0, r = n - 1;
            while (l < r) {
                if (sortedDeg[l] + sortedDeg[r] > q) {
                    count += (r - l);
                    r--;
                } else {
                    l++;
                }
            }

            for (Map.Entry<Long, Integer> entry : shared.entrySet()) {
                long key = entry.getKey();
                int u = (int)(key >>> 32);
                int v = (int)(key & 0xFFFFFFFFL);
                int edgeCount = entry.getValue();
                if (deg[u] + deg[v] > q && deg[u] + deg[v] - edgeCount <= q) {
                    count--;
                }
            }
            ans[qi] = count;
        }
        return ans;
    }
}

/**
 * @param {number} n
 * @param {number[][]} edges
 * @param {number[]} queries
 * @return {number[]}
 */
var countPairs = function(n, edges, queries) {
    const deg = Array(n + 1).fill(0);
    const shared = new Map();
    for (const [u, v] of edges) {
        deg[u]++;
        deg[v]++;
        const minNode = Math.min(u, v);
        const maxNode = Math.max(u, v);
        const key = `${minNode},${maxNode}`;
        shared.set(key, (shared.get(key) || 0) + 1);
    }

    const sortedDeg = deg.slice(1).sort((a, b) => a - b);
    const ans = [];

    for (const q of queries) {
        let count = 0;
        let l = 0, r = n - 1;
        while (l < r) {
            if (sortedDeg[l] + sortedDeg[r] > q) {
                count += (r - l);
                r--;
            } else {
                l++;
            }
        }

        for (const [key, edgeCount] of shared) {
            const [u, v] = key.split(',').map(Number);
            if (deg[u] + deg[v] > q && deg[u] + deg[v] - edgeCount <= q) {
                count--;
            }
        }
        ans.push(count);
    }
    return ans;
};
